insert into public.galaxy_items(kind,data,author) values
('memory','{"kind":"memory","title":"Donde comenzó todo","body":"Todavía me acuerdo de nuestra primera cita, pintando a Candelario y a Pocho. Dos perritos de cerámica que terminaron guardando el recuerdo del comienzo de algo que ninguno de los dos sabía hasta dónde nos iba a llevar.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0'),
('memory','{"kind":"memory","title":"Nuestra segunda cita","body":"Después vino el estadio, el Inter de Bogotá y nuestra segunda cita. Y poco a poco empezamos a llenar nuestra historia de planes, lugares y momentos que ahora me encanta poder llamar nuestros.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0'),
('memory','{"kind":"memory","title":"Boyacá","body":"Nuestro viaje a Boyacá, conocer a tus tías y compartir contigo fuera de nuestra rutina. Me gusta pensar en todos esos lugares que ahora significan un poquito más para mí simplemente porque estuve ahí contigo.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0'),
('memory','{"kind":"memory","title":"Nuestra primera noche","body":"Y cómo olvidar nuestra primera noche juntos... especialmente porque casi logro espantarte con mis ronquidos. No fue precisamente mi momento más seductor, pero al menos sobreviviste para contarlo.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0'),
('memory','{"kind":"memory","title":"Útica","body":"Contigo también descubrí algo importantísimo sobre mi futuro: cuando sea un viejito quiero estar pescando desde un puente con una rueda de nailon. Suena absurdo, pero ese recuerdo contigo me hace imaginar todos esos pequeños momentos que todavía quiero vivir.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0'),
('memory','{"kind":"memory","title":"Cuatro meses","body":"Solo han pasado cuatro meses, Adri. Cuatro meses desde que empezamos esta historia y ya tenemos viajes, perritos de cerámica, estadios, noches juntos, aventuras y recuerdos que me hacen sonreír mientras escribo esto. Y todavía nos falta muchísimo.","date":"","category":"Nuestra historia","done":false,"annual":false}'::jsonb,'0');